  /* 品牌色 */
  --td-brand-color: #3b82f6;
  --td-brand-color-hover: #60a5fa;
  --td-brand-color-active: #2563eb;
  --td-brand-color-light: rgba(59, 130, 246, 0.1);

  /* 背景色 - 浅色模式 */
  --td-bg-color-page: #ffffff;
  --td-bg-color-container: #fafafa;
  --td-bg-color-container-hover: #f5f5f5;
  --td-bg-color-container-active: #eeeeee;
  --td-bg-color-secondarycontainer: #f5f5f5;
  --td-bg-color-secondarycontainer-hover: #eeeeee;
  --td-bg-color-component: #f5f5f5;
  --td-bg-color-component-hover: #eeeeee;
  --td-bg-color-component-disabled: #f5f5f5;

  /* 文字色 - 浅色模式 */
  --td-text-color-primary: #171717;
  --td-text-color-secondary: #737373;
  --td-text-color-placeholder: #a3a3a3;
  --td-text-color-disabled: #d4d4d4;
  --td-text-color-anti: #ffffff;

  /* 边框色 - 浅色模式 */
  --td-border-level-1-color: #e5e5e5;
  --td-border-level-2-color: #d4d4d4;
  --td-component-stroke: #e5e5e5;
  --td-component-border: #e5e5e5;

  /* 遮罩 */
