])
const TASK_KEYS = new Set([
  'schema', 'runId', 'agendaItemId', 'seatId', 'taskClass', 'reviewMode', 'revision',
  'decisionQuestion', 'factSlices', 'evidenceRefs', 'firstRoundIsolation', 'returnTo',
